def compute(vars):
    debt = vars["v1"]
    total = vars["v2"]
    if total == 0:
        return None
    value = debt / total * 100
    return {
        "value": value,
        "trace": {
            "long_term_debt": debt,
            "total_contractual_obligations": total,
            "percentage": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
